Az alábbi index.html sablon magában foglalja a magyar nyelvű AI chat felületet, a PWA‐manifeszt hivatkozását, a service worker regisztrációt és iPhone‐on natív fullscreen megnyitást a safe‐area szabvány használatával.[1]

```html
<!DOCTYPE html>
<html lang="hu">
<head>
  <meta charset="UTF-8">
  <meta http-equiv="X-UA-Compatible" content="IE=edge">
  <title>AI Chat App</title>

  <!-- Fullscreen PWA iOS support -->
  <meta name="viewport" content="width=device-width, initial-scale=1, maximum-scale=1, viewport-fit=cover">
  <meta name="apple-mobile-web-app-capable" content="yes">
  <meta name="apple-mobile-web-app-status-bar-style" content="black-translucent">

  <!-- PWA manifest -->
  <link rel="manifest" href="manifest.json">

  <!-- CSS reset & safe-area padding -->
  <style>
    html, body {
      margin: 0;
      padding: 0;
      height: 100vh;
      background: #f2f2f7;
      /* iPhone notch / home indicator safe area */
      padding-top: env(safe-area-inset-top);
      padding-bottom: env(safe-area-inset-bottom);
      padding-left: env(safe-area-inset-left);
      padding-right: env(safe-area-inset-right);
      display: flex;
      flex-direction: column;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    }
    #chat {
      flex: 1;
      overflow-y: auto;
      padding: 1rem;
    }
    .message {
      margin-bottom: 1em;
      line-height: 1.4;
    }
    .user { text-align: right; }
    .bot { text-align: left; color: #333; }
    #input-area {
      display: flex;
      border-top: 1px solid #ccc;
      padding: 0.5rem;
    }
    #input {
      flex: 1;
      padding: 0.5rem;
      font-size: 1rem;
    }
    #send {
      padding: 0.5rem 1rem;
      margin-left: 0.5rem;
      font-size: 1rem;
      background: #007aff;
      color: #fff;
      border: none;
      border-radius: 5px;
    }
  </style>
</head>
<body>
  <div id="chat"></div>
  <div id="input-area">
    <input id="input" type="text" placeholder="Írj egy üzenetet…" />
    <button id="send">Küldés</button>
  </div>

  <script>
    // Üzenetek megjelenítése
    const chat = document.getElementById('chat');
    function addMessage(text, cls) {
      const div = document.createElement('div');
      div.className = 'message ' + cls;
      div.textContent = text;
      chat.appendChild(div);
      chat.scrollTop = chat.scrollHeight;
    }

    // OpenAI API hívás (példa)
    async function sendToAI(prompt) {
      const response = await fetch('', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ model: 'gpt-4', messages: [{ role: 'user', content: prompt }] })
      });
      const data = await response.json();
      return data.choices[0].message.content;
    }

    // Küldés kezelése
    document.getElementById('send').addEventListener('click', async () => {
      const inputEl = document.getElementById('input');
      const text = inputEl.value.trim();
      if (!text) return;
      addMessage(text, 'user');
      inputEl.value = '';
      addMessage('Gépelés...', 'bot');
      const reply = await sendToAI(text);
      // Utolsó “Gépelés...” törlése
      chat.lastChild.remove();
      addMessage(reply, 'bot');
    });

    // Service worker regisztráció PWA-hoz
    if ('serviceWorker' in navigator) {
      navigator.serviceWorker.register('sw.js')
        .then(() => console.log('Service Worker regisztrálva'))
        .catch(err => console.error('SW hiba:', err));
    }
  </script>
</body>
</html>
```
